import { useState, useEffect } from 'react';
import { useStore } from './store';
import { shallow } from 'zustand/shallow';
import { Play, X, CheckCircle, XCircle, GitBranch, Share2, Zap, KeyRound, ChevronDown, ChevronUp } from 'lucide-react';

const selector = (s) => ({ nodes: s.nodes, edges: s.edges });

const overlayStyle = {
  position: 'fixed', inset: 0,
  background: 'rgba(0,0,0,0.65)',
  backdropFilter: 'blur(4px)',
  display: 'flex', alignItems: 'center', justifyContent: 'center',
  zIndex: 9999,
  fontFamily: "'Inter', system-ui, sans-serif",
};

const closeBtnStyle = {
  background: 'transparent', border: 'none',
  color: '#55556a', cursor: 'pointer',
  display: 'flex', alignItems: 'center', padding: 4, borderRadius: 6,
};

/* ── DAG Result Modal (Submit Pipeline) ── */
const DagResultModal = ({ result, error, onClose }) => {
  if (!result && !error) return null;

  const isDAG  = result?.is_dag;
  const accent = error ? '#f87171' : isDAG ? '#34d399' : '#fb923c';

  return (
    <div onClick={onClose} style={overlayStyle}>
      <div
        onClick={e => e.stopPropagation()}
        style={{
          background: '#111118',
          border: `1px solid ${accent}44`,
          borderTop: `3px solid ${accent}`,
          borderRadius: 14,
          width: 360,
          boxShadow: `0 8px 40px #00000090, 0 0 0 1px ${accent}22`,
          overflow: 'hidden',
          animation: 'modalIn 0.18s ease',
        }}
      >
        <div style={{
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          padding: '14px 16px 12px',
          borderBottom: '1px solid #1e1e2a',
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            {error
              ? <XCircle size={16} color="#f87171" />
              : isDAG
                ? <CheckCircle size={16} color="#34d399" />
                : <XCircle size={16} color="#fb923c" />
            }
            <span style={{ color: '#e8e8f0', fontWeight: 700, fontSize: 14 }}>
              Pipeline Analysis
            </span>
          </div>
          <button onClick={onClose} style={closeBtnStyle}
            onMouseEnter={e => { e.currentTarget.style.color = '#e8e8f0'; e.currentTarget.style.background = '#1e1e2a'; }}
            onMouseLeave={e => { e.currentTarget.style.color = '#55556a'; e.currentTarget.style.background = 'transparent'; }}>
            <X size={14} />
          </button>
        </div>

        <div style={{ padding: '16px 18px' }}>
          {error ? (
            <div>
              <p style={{ color: '#f87171', fontSize: 13, lineHeight: 1.6, margin: 0 }}>{error}</p>
              <p style={{ color: '#55556a', fontSize: 11, marginTop: 10, lineHeight: 1.5 }}>
                Make sure the backend is running:<br />
                <code style={{ color: '#8888a8', background: '#0a0a0f', padding: '2px 6px', borderRadius: 4, fontSize: 11 }}>
                  uvicorn main:app --reload
                </code>
              </p>
            </div>
          ) : (
            <>
              <div style={{ display: 'flex', gap: 10, marginBottom: 14 }}>
                <StatCard icon={<Share2 size={14} />} label="Nodes" value={result.num_nodes} />
                <StatCard icon={<GitBranch size={14} />} label="Edges" value={result.num_edges} />
              </div>
              <div style={{
                background: isDAG ? '#0d2b1f' : '#2b1a0d',
                border: `1px solid ${isDAG ? '#34d39933' : '#fb923c33'}`,
                borderRadius: 8,
                padding: '10px 14px',
                display: 'flex', alignItems: 'flex-start', gap: 10,
              }}>
                {isDAG
                  ? <CheckCircle size={15} color="#34d399" style={{ flexShrink: 0, marginTop: 1 }} />
                  : <XCircle    size={15} color="#fb923c" style={{ flexShrink: 0, marginTop: 1 }} />
                }
                <div>
                  <p style={{ color: isDAG ? '#34d399' : '#fb923c', fontWeight: 700, fontSize: 12, margin: '0 0 2px' }}>
                    {isDAG ? 'Valid DAG' : 'Cycle Detected'}
                  </p>
                  <p style={{ color: '#8888a8', fontSize: 11, lineHeight: 1.5, margin: 0 }}>
                    {isDAG
                      ? 'No cycles found. This pipeline can be executed safely.'
                      : 'The pipeline contains a cycle and cannot be executed as-is.'}
                  </p>
                </div>
              </div>
            </>
          )}
        </div>

        <div style={{ padding: '10px 18px 14px', display: 'flex', justifyContent: 'flex-end' }}>
          <button onClick={onClose} style={footerBtnStyle}
            onMouseEnter={e => e.currentTarget.style.background = '#2a2a3a'}
            onMouseLeave={e => e.currentTarget.style.background = '#1e1e2a'}>
            Close
          </button>
        </div>
      </div>
      <style>{`@keyframes modalIn { from { opacity: 0; transform: scale(0.95) translateY(8px); } to { opacity: 1; transform: scale(1) translateY(0); } }`}</style>
    </div>
  );
};

const footerBtnStyle = {
  background: '#1e1e2a',
  border: '1px solid #2a2a3a',
  borderRadius: 7,
  color: '#e8e8f0',
  fontSize: 12,
  fontWeight: 600,
  padding: '7px 18px',
  cursor: 'pointer',
  fontFamily: "'Inter', system-ui, sans-serif",
  transition: 'background 0.15s',
};

const StatCard = ({ icon, label, value }) => (
  <div style={{
    flex: 1, background: '#0a0a0f', border: '1px solid #2a2a3a', borderRadius: 8,
    padding: '10px 12px', display: 'flex', flexDirection: 'column', gap: 4,
  }}>
    <div style={{ display: 'flex', alignItems: 'center', gap: 5, color: '#55556a' }}>
      {icon}
      <span style={{ fontSize: 10, fontWeight: 600, letterSpacing: 0.5, textTransform: 'uppercase' }}>{label}</span>
    </div>
    <span style={{ fontSize: 24, fontWeight: 700, color: '#e8e8f0', lineHeight: 1 }}>{value}</span>
  </div>
);

/* ── API Key Prompt Modal ── */
const ApiKeyModal = ({ onRun, onClose }) => {
  const [key, setKey] = useState(() => sessionStorage.getItem('vs_api_key') || '');
  // Note: sessionStorage works fine outside the artifacts sandbox (this is a real React app, not a Claude artifact).

  return (
    <div onClick={onClose} style={overlayStyle}>
      <div onClick={e => e.stopPropagation()} style={{
        background: '#111118', border: '1px solid #2a2a3a', borderTop: '3px solid #6366f1',
        borderRadius: 14, width: 380, boxShadow: '0 8px 40px #00000090', overflow: 'hidden',
        animation: 'modalIn 0.18s ease',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '14px 16px 12px', borderBottom: '1px solid #1e1e2a' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <KeyRound size={16} color="#6366f1" />
            <span style={{ color: '#e8e8f0', fontWeight: 700, fontSize: 14 }}>Run Pipeline</span>
          </div>
          <button onClick={onClose} style={closeBtnStyle}
            onMouseEnter={e => { e.currentTarget.style.color = '#e8e8f0'; e.currentTarget.style.background = '#1e1e2a'; }}
            onMouseLeave={e => { e.currentTarget.style.color = '#55556a'; e.currentTarget.style.background = 'transparent'; }}>
            <X size={14} />
          </button>
        </div>

        <div style={{ padding: '16px 18px' }}>
          <p style={{ color: '#8888a8', fontSize: 12, lineHeight: 1.6, margin: '0 0 12px' }}>
            Executing this pipeline will call a real LLM provider for any LLM node.
            Paste an OpenAI or Anthropic API key — it's sent directly to your local
            backend for this run only and is never saved on a server.
          </p>
          <label style={{ display: 'block', fontSize: 10, color: '#55556a', fontWeight: 600, letterSpacing: 0.5, textTransform: 'uppercase', marginBottom: 4 }}>
            API Key
          </label>
          <input
            type="password"
            value={key}
            onChange={e => setKey(e.target.value)}
            placeholder="sk-... or sk-ant-..."
            style={{
              width: '100%', background: '#0a0a0f', border: '1px solid #2a2a3a', borderRadius: 6,
              color: '#e8e8f0', fontSize: 12, padding: '8px 10px', outline: 'none', boxSizing: 'border-box',
              fontFamily: "'JetBrains Mono', monospace",
            }}
          />
          <p style={{ color: '#55556a', fontSize: 11, marginTop: 8, lineHeight: 1.5 }}>
            The model picked in each LLM node decides the provider automatically
            (e.g. <code>gpt-4o</code> → OpenAI, <code>claude-3-5-sonnet</code> → Anthropic).
          </p>
        </div>

        <div style={{ padding: '10px 18px 14px', display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
          <button onClick={onClose} style={footerBtnStyle}
            onMouseEnter={e => e.currentTarget.style.background = '#2a2a3a'}
            onMouseLeave={e => e.currentTarget.style.background = '#1e1e2a'}>
            Cancel
          </button>
          <button
            onClick={() => {
              sessionStorage.setItem('vs_api_key', key);
              onRun(key);
            }}
            style={{ ...footerBtnStyle, background: '#6366f1', border: 'none', color: '#fff' }}
            onMouseEnter={e => e.currentTarget.style.background = '#4f52d9'}
            onMouseLeave={e => e.currentTarget.style.background = '#6366f1'}
          >
            Run Pipeline
          </button>
        </div>
      </div>
    </div>
  );
};

/* ── Run Result Modal ── */
const RunResultModal = ({ data, error, onClose }) => {
  const [traceOpen, setTraceOpen] = useState(false);
  if (!data && !error) return null;

  const success = data?.success;
  const accent = error || (data && !success) ? '#f87171' : '#34d399';
  const outputs = data?.outputs || {};
  const trace = data?.trace || [];
  const outputEntries = Object.entries(outputs);

  return (
    <div onClick={onClose} style={overlayStyle}>
      <div onClick={e => e.stopPropagation()} style={{
        background: '#111118', border: `1px solid ${accent}44`, borderTop: `3px solid ${accent}`,
        borderRadius: 14, width: 440, maxHeight: '80vh', display: 'flex', flexDirection: 'column',
        boxShadow: `0 8px 40px #00000090, 0 0 0 1px ${accent}22`, overflow: 'hidden',
        animation: 'modalIn 0.18s ease',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '14px 16px 12px', borderBottom: '1px solid #1e1e2a', flexShrink: 0 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            {error || !success
              ? <XCircle size={16} color="#f87171" />
              : <CheckCircle size={16} color="#34d399" />}
            <span style={{ color: '#e8e8f0', fontWeight: 700, fontSize: 14 }}>Run Result</span>
          </div>
          <button onClick={onClose} style={closeBtnStyle}
            onMouseEnter={e => { e.currentTarget.style.color = '#e8e8f0'; e.currentTarget.style.background = '#1e1e2a'; }}
            onMouseLeave={e => { e.currentTarget.style.color = '#55556a'; e.currentTarget.style.background = 'transparent'; }}>
            <X size={14} />
          </button>
        </div>

        <div style={{ padding: '16px 18px', overflowY: 'auto', flex: 1 }}>
          {(error || (data && !success)) ? (
            <div style={{
              background: '#2b0d0d', border: '1px solid #f8717133', borderRadius: 8,
              padding: '10px 14px', display: 'flex', alignItems: 'flex-start', gap: 10, marginBottom: 14,
            }}>
              <XCircle size={15} color="#f87171" style={{ flexShrink: 0, marginTop: 1 }} />
              <p style={{ color: '#f87171', fontSize: 12, lineHeight: 1.6, margin: 0 }}>
                {error || data?.error}
              </p>
            </div>
          ) : (
            <div style={{
              background: '#0d2b1f', border: '1px solid #34d39933', borderRadius: 8,
              padding: '10px 14px', display: 'flex', alignItems: 'flex-start', gap: 10, marginBottom: 14,
            }}>
              <CheckCircle size={15} color="#34d399" style={{ flexShrink: 0, marginTop: 1 }} />
              <p style={{ color: '#34d399', fontSize: 12, lineHeight: 1.6, margin: 0, fontWeight: 600 }}>
                Pipeline executed successfully.
              </p>
            </div>
          )}

          {outputEntries.length > 0 && (
            <div style={{ marginBottom: 14 }}>
              <p style={{ fontSize: 10, color: '#55556a', fontWeight: 600, letterSpacing: 0.5, textTransform: 'uppercase', margin: '0 0 8px' }}>
                Output values
              </p>
              {outputEntries.map(([name, value]) => (
                <div key={name} style={{
                  background: '#0a0a0f', border: '1px solid #2a2a3a', borderRadius: 8,
                  padding: '10px 12px', marginBottom: 8,
                }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 4 }}>
                    <Zap size={11} color="#ec4899" />
                    <span style={{ fontSize: 11, fontWeight: 700, color: '#ec4899' }}>{name}</span>
                  </div>
                  <p style={{
                    color: '#e8e8f0', fontSize: 12, lineHeight: 1.6, margin: 0,
                    whiteSpace: 'pre-wrap', fontFamily: "'JetBrains Mono', monospace",
                    wordBreak: 'break-word',
                  }}>
                    {typeof value === 'string' ? value : JSON.stringify(value, null, 2)}
                  </p>
                </div>
              ))}
            </div>
          )}

          {trace.length > 0 && (
            <div>
              <button
                onClick={() => setTraceOpen(v => !v)}
                style={{
                  width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                  background: 'transparent', border: '1px solid #2a2a3a', borderRadius: 6,
                  color: '#55556a', fontSize: 11, padding: '6px 10px', cursor: 'pointer',
                  fontFamily: "'Inter', system-ui, sans-serif",
                }}
              >
                <span>Execution trace ({trace.length} steps)</span>
                {traceOpen ? <ChevronUp size={12} /> : <ChevronDown size={12} />}
              </button>
              {traceOpen && (
                <div style={{ marginTop: 8, display: 'flex', flexDirection: 'column', gap: 6 }}>
                  {trace.map((step, i) => (
                    <div key={i} style={{
                      display: 'flex', gap: 8, fontSize: 11, padding: '6px 8px',
                      background: '#0a0a0f', borderRadius: 6,
                      borderLeft: `2px solid ${step.status === 'error' ? '#f87171' : '#34d399'}`,
                    }}>
                      <span style={{ color: '#55556a', flexShrink: 0, fontFamily: "'JetBrains Mono', monospace" }}>{step.type}</span>
                      <span style={{ color: '#8888a8', wordBreak: 'break-word' }}>{step.detail}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        <div style={{ padding: '10px 18px 14px', display: 'flex', justifyContent: 'flex-end', flexShrink: 0 }}>
          <button onClick={onClose} style={footerBtnStyle}
            onMouseEnter={e => e.currentTarget.style.background = '#2a2a3a'}
            onMouseLeave={e => e.currentTarget.style.background = '#1e1e2a'}>
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

/* ── Submit Button (DAG validation only) ── */
export const SubmitButton = () => {
  const { nodes, edges } = useStore(selector, shallow);
  const [loading, setLoading] = useState(false);
  const [result,  setResult]  = useState(null);
  const [error,   setError]   = useState(null);

  const [showKeyModal, setShowKeyModal] = useState(false);
  const [runLoading,   setRunLoading]   = useState(false);
  const [runData,      setRunData]      = useState(null);
  const [runError,     setRunError]     = useState(null);

  const handleSubmit = async () => {
    setLoading(true);
    setResult(null);
    setError(null);
    try {
      const res = await fetch('http://localhost:8000/pipelines/parse', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ nodes, edges }),
      });
      if (!res.ok) throw new Error(`Server error: ${res.status}`);
      const data = await res.json();
      setResult(data);
    } catch (err) {
      setError(`Could not reach backend.\n\n${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleRun = async (apiKey) => {
    setShowKeyModal(false);
    setRunLoading(true);
    setRunData(null);
    setRunError(null);
    try {
      const res = await fetch('http://localhost:8000/pipelines/run', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ nodes, edges, api_key: apiKey || null }),
      });
      if (!res.ok) throw new Error(`Server error: ${res.status}`);
      const data = await res.json();
      setRunData(data);
    } catch (err) {
      setRunError(`Could not reach backend.\n\n${err.message}`);
    } finally {
      setRunLoading(false);
    }
  };

  return (
    <>
      <DagResultModal
        result={result}
        error={error}
        onClose={() => { setResult(null); setError(null); }}
      />
      {showKeyModal && (
        <ApiKeyModal onRun={handleRun} onClose={() => setShowKeyModal(false)} />
      )}
      <RunResultModal
        data={runData}
        error={runError}
        onClose={() => { setRunData(null); setRunError(null); }}
      />

      <div style={{
        height: 52,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 10,
        background: '#111118',
        borderTop: '1px solid #1e1e2a',
        flexShrink: 0,
      }}>
        <button
          onClick={handleSubmit}
          disabled={loading}
          style={{
            display: 'flex', alignItems: 'center', gap: 7,
            background: loading ? '#4346a8' : '#6366f1',
            color: '#fff', border: 'none', borderRadius: 7, padding: '8px 22px',
            fontSize: 13, fontWeight: 600, cursor: loading ? 'not-allowed' : 'pointer',
            letterSpacing: 0.2, fontFamily: "'Inter', system-ui, sans-serif",
            transition: 'background 0.15s, box-shadow 0.15s',
            boxShadow: '0 2px 12px #6366f140', opacity: loading ? 0.75 : 1,
          }}
          onMouseEnter={e => { if (!loading) { e.currentTarget.style.background = '#4f52d9'; e.currentTarget.style.boxShadow = '0 4px 20px #6366f160'; } }}
          onMouseLeave={e => { if (!loading) { e.currentTarget.style.background = '#6366f1'; e.currentTarget.style.boxShadow = '0 2px 12px #6366f140'; } }}
        >
          {loading
            ? <span style={{ width: 13, height: 13, border: '2px solid #ffffff60', borderTop: '2px solid #fff', borderRadius: '50%', display: 'inline-block', animation: 'spin 0.7s linear infinite' }} />
            : <GitBranch size={13} strokeWidth={2.5} />
          }
          {loading ? 'Analyzing…' : 'Submit Pipeline'}
        </button>

        <button
          onClick={() => setShowKeyModal(true)}
          disabled={runLoading}
          style={{
            display: 'flex', alignItems: 'center', gap: 7,
            background: runLoading ? '#0d8a5f' : '#10b981',
            color: '#fff', border: 'none', borderRadius: 7, padding: '8px 22px',
            fontSize: 13, fontWeight: 600, cursor: runLoading ? 'not-allowed' : 'pointer',
            letterSpacing: 0.2, fontFamily: "'Inter', system-ui, sans-serif",
            transition: 'background 0.15s, box-shadow 0.15s',
            boxShadow: '0 2px 12px #10b98140', opacity: runLoading ? 0.75 : 1,
          }}
          onMouseEnter={e => { if (!runLoading) { e.currentTarget.style.background = '#0ea271'; e.currentTarget.style.boxShadow = '0 4px 20px #10b98160'; } }}
          onMouseLeave={e => { if (!runLoading) { e.currentTarget.style.background = '#10b981'; e.currentTarget.style.boxShadow = '0 2px 12px #10b98140'; } }}
        >
          {runLoading
            ? <span style={{ width: 13, height: 13, border: '2px solid #ffffff60', borderTop: '2px solid #fff', borderRadius: '50%', display: 'inline-block', animation: 'spin 0.7s linear infinite' }} />
            : <Play size={13} strokeWidth={2.5} />
          }
          {runLoading ? 'Running…' : 'Run Pipeline'}
        </button>
      </div>

      <style>{`
        @keyframes spin { to { transform: rotate(360deg); } }
      `}</style>
    </>
  );
};
